using System; using System.Data; using System.Data.SqlClient; using System.Collections.Generic; using RetailSales.DTO;
namespace RetailSales.DAL {
public class RetailDAL {
 public DataTable Query(string sql, params SqlParameter[] ps){using(var c=Db.Open())using(var a=new SqlDataAdapter(sql,c)){if(ps!=null)a.SelectCommand.Parameters.AddRange(ps);var t=new DataTable();a.Fill(t);return t;}}
 public int Exec(string sql, params SqlParameter[] ps){using(var c=Db.Open())using(var x=new SqlCommand(sql,c)){if(ps!=null)x.Parameters.AddRange(ps);return x.ExecuteNonQuery();}}
 public DataTable SearchProducts(string key){return Query("SELECT MaSP,TenSP,GiaBan,SoLuongTon FROM SanPham WHERE MaSP LIKE @k OR TenSP LIKE @k",new SqlParameter("@k", "%"+key+"%"));}
 public void SaveSale(int maNV,int? maKH,List<CartItem> cart){using(var c=Db.Open())using(var tr=c.BeginTransaction()){try{decimal total=0;foreach(var i in cart)total+=i.ThanhTien;int maHD;using(var cmd=new SqlCommand("INSERT HoaDon(MaNV,MaKH,TongTien) VALUES(@nv,@kh,@tt); SELECT CAST(SCOPE_IDENTITY() AS INT)",c,tr)){cmd.Parameters.Add("@nv",SqlDbType.Int).Value=maNV;cmd.Parameters.Add("@kh",SqlDbType.Int).Value=(object)maKH??DBNull.Value;cmd.Parameters.Add("@tt",SqlDbType.Decimal).Value=total;cmd.Parameters["@tt"].Precision=18;cmd.Parameters["@tt"].Scale=2;maHD=(int)cmd.ExecuteScalar();}
 foreach(var i in cart){using(var cmd=new SqlCommand("UPDATE SanPham SET SoLuongTon=SoLuongTon-@sl WHERE MaSP=@sp AND SoLuongTon>=@sl",c,tr)){cmd.Parameters.Add("@sl",SqlDbType.Int).Value=i.SoLuong;cmd.Parameters.Add("@sp",SqlDbType.VarChar,20).Value=i.MaSP;if(cmd.ExecuteNonQuery()!=1)throw new Exception("Sản phẩm "+i.MaSP+" không đủ tồn kho. Giao dịch đã được hoàn tác.");}using(var cmd=new SqlCommand("INSERT ChiTietHoaDon(MaHD,MaSP,SoLuong,DonGia) VALUES(@hd,@sp,@sl,@gia)",c,tr)){cmd.Parameters.AddWithValue("@hd",maHD);cmd.Parameters.Add("@sp",SqlDbType.VarChar,20).Value=i.MaSP;cmd.Parameters.AddWithValue("@sl",i.SoLuong);var p=cmd.Parameters.Add("@gia",SqlDbType.Decimal);p.Precision=18;p.Scale=2;p.Value=i.DonGia;cmd.ExecuteNonQuery();}}
 if(maKH.HasValue){using(var cmd=new SqlCommand("UPDATE KhachHang SET DiemTichLuy=DiemTichLuy+@diem WHERE MaKH=@kh",c,tr)){cmd.Parameters.Add("@diem",SqlDbType.Int).Value=(int)(total/100000m);cmd.Parameters.Add("@kh",SqlDbType.Int).Value=maKH.Value;cmd.ExecuteNonQuery();}}tr.Commit();}catch{tr.Rollback();throw;}}}
 public decimal Scalar(string sql){using(var c=Db.Open())using(var x=new SqlCommand(sql,c)){object v=x.ExecuteScalar();return v==DBNull.Value?0:Convert.ToDecimal(v);}}
}
}